/// of sending the whole page.
async fn write_batch_partial(
    &self,
    records: &[Value],
) -> Result<Vec<faucet_core::RowOutcome>, FaucetError> {
    if matches!(self.config.write.write_mode, faucet_core::WriteMode::Append) {
        self.write_batch(records).await?;
