async fn delete_by_keys(
    &self,
    tx: &mut sqlx::Transaction<'_, sqlx::Sqlite>,
    deletes: &[faucet_core::KeyTuple],
) -> Result<usize, FaucetError> {
    if deletes.is_empty() {
