        .iter()
        .map(|k| quote_ident(k))
        .collect::<Vec<_>>()
        .join(", ");

    const MAX_SQLITE_VARS: usize = 32766;
    let per = (MAX_SQLITE_VARS / key.len().max(1)).max(1);
    let mut total = 0usize;

    for chunk in deletes.chunks(per) {
        let tuples: Vec<String> = chunk
            .iter()
            .map(|_| format!("({})", vec!["?"; key.len()].join(", ")))
            .collect();
