#[test]
fn overwrite_commit_sql_swaps_in_a_transaction() {
    let target = table_ref("p", "d", "t");
    let temp = table_ref("p", "d", "t__faucet_ovw");
    let sql = build_overwrite_commit_sql(&target, &temp);
    assert!(sql.starts_with("BEGIN TRANSACTION;"));
