1	//! Schema-driven SQL generation for the BigQuery exactly-once write path (#215).
2	//!
3	//! All functions here are **pure** (no I/O): given the target table's schema as
4	//! [`FieldSpec`]s, they generate the SQL for the atomic
5	//! `INSERT … SELECT FROM UNNEST(JSON_QUERY_ARRAY(@payload))` + watermark `MERGE`
6	//! transaction that makes a page's rows and its commit token land atomically.
7	//! See `docs/superpowers/specs/2026-06-10-bigquery-exactly-once-design.md`.
8	
9	use faucet_core::idempotency::{
10	    COMMIT_TOKEN_SCOPE_COL, COMMIT_TOKEN_TABLE, COMMIT_TOKEN_TOKEN_COL,
11	};
12	use gcp_bigquery_client::model::field_type::FieldType;
13	use gcp_bigquery_client::model::table_field_schema::TableFieldSchema;
14	
15	/// A normalized BigQuery column spec — the sink's own mirror of the client's
16	/// `TableFieldSchema`, so the SQL generator is independent of the client model
17	/// and trivially constructible in unit tests.
18	#[derive(Debug, Clone, PartialEq, Eq)]
19	pub struct FieldSpec {
20	    /// Column / field name (a valid BigQuery identifier, since it came from
21	    /// BigQuery's own schema).
22	    pub name: String,
23	    /// Normalized type.
24	    pub ty: BqType,
25	    /// `true` for a `REPEATED` (array) column.
26	    pub repeated: bool,
27	    /// Sub-fields for `STRUCT`/`RECORD` columns (empty otherwise).
28	    pub fields: Vec<FieldSpec>,
29	}
30	
31	/// Normalized BigQuery type, collapsing the client's alias variants
32	/// (`INT64`=`INTEGER`, `FLOAT64`=`FLOAT`, `BOOL`=`BOOLEAN`, `STRUCT`=`RECORD`).
33	#[derive(Debug, Clone, PartialEq, Eq)]
34	pub enum BqType {
35	    String,
36	    Bytes,
37	    Int64,
38	    Float64,
39	    Numeric,
40	    BigNumeric,
41	    Bool,
42	    Timestamp,
43	    Date,
44	    Time,
45	    Datetime,
46	    Interval,
47	    Geography,
48	    Json,
49	    Struct,
50	}
51	
52	impl BqType {
53	    /// Map the client's `FieldType` discriminant to a normalized [`BqType`].
54	    pub fn from_field_type(ft: &FieldType) -> Self {
55	        match ft {
56	            FieldType::String => BqType::String,
57	            FieldType::Bytes => BqType::Bytes,
58	            FieldType::Integer | FieldType::Int64 => BqType::Int64,
59	            FieldType::Float | FieldType::Float64 => BqType::Float64,
60	            FieldType::Numeric => BqType::Numeric,
61	            FieldType::Bignumeric => BqType::BigNumeric,
62	            FieldType::Boolean | FieldType::Bool => BqType::Bool,
63	            FieldType::Timestamp => BqType::Timestamp,
64	            FieldType::Date => BqType::Date,
65	            FieldType::Time => BqType::Time,
66	            FieldType::Datetime => BqType::Datetime,
67	            FieldType::Interval => BqType::Interval,
68	            FieldType::Geography => BqType::Geography,
69	            FieldType::Json => BqType::Json,
70	            FieldType::Record | FieldType::Struct => BqType::Struct,
71	        }
72	    }
73	
74	    /// The BigQuery SQL type keyword used in a `CAST(... AS <kw>)` / array
75	    /// element type.
76	    fn sql_keyword(&self) -> &'static str {
77	        match self {
78	            BqType::String => "STRING",
79	            BqType::Bytes => "BYTES",
80	            BqType::Int64 => "INT64",
81	            BqType::Float64 => "FLOAT64",
82	            BqType::Numeric => "NUMERIC",
83	            BqType::BigNumeric => "BIGNUMERIC",
84	            BqType::Bool => "BOOL",
85	            BqType::Timestamp => "TIMESTAMP",
86	            BqType::Date => "DATE",
87	            BqType::Time => "TIME",
88	            BqType::Datetime => "DATETIME",
89	            BqType::Interval => "INTERVAL",
90	            BqType::Geography => "GEOGRAPHY",
91	            BqType::Json => "JSON",
92	            BqType::Struct => "STRUCT",
93	        }
94	    }
95	}
96	
97	impl FieldSpec {
98	    /// Convert a client `TableFieldSchema` (possibly nested) into a [`FieldSpec`].
99	    pub fn from_table_field(f: &TableFieldSchema) -> Self {
100	        let repeated = f.mode.as_deref() == Some("REPEATED");
101	        let ty = BqType::from_field_type(&f.r#type);
102	        let fields = f
103	            .fields
104	            .as_ref()
105	            .map(|sub| sub.iter().map(FieldSpec::from_table_field).collect())
106	            .unwrap_or_default();
107	        FieldSpec {
108	            name: f.name.clone(),
109	            ty,
110	            repeated,
111	            fields,
112	        }
113	    }
114	}
115	
116	/// SQL string literal for a path/value: single-quoted with `\` and `'` escaped
117	/// (BigQuery accepts backslash escapes in quoted strings).
118	pub(crate) fn sql_str(s: &str) -> String {
119	    format!("'{}'", s.replace('\\', "\\\\").replace('\'', "\\'"))
120	}
121	
122	/// Backtick-quoted identifier. BigQuery identifiers never contain a backtick
123	/// (the schema came from BigQuery), so a stray one is stripped defensively.
124	pub(crate) fn quote_ident(name: &str) -> String {
125	    format!("`{}`", name.replace('`', ""))
126	}
127	
128	/// A single JSONPath member segment. Safe BigQuery identifiers use the `.name`
129	/// form; anything else is bracket-quoted (`['weird.name']`).
130	pub(crate) fn json_path_segment(name: &str) -> String {
131	    let safe = match name.chars().next() {
132	        Some(c) if c.is_ascii_alphabetic() || c == '_' => {
133	            name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
134	        }
135	        _ => false,
136	    };
137	    if safe {
138	        format!(".{name}")
139	    } else {
140	        let esc = name.replace('\\', "\\\\").replace('\'', "\\'");
141	        format!("['{esc}']")
142	    }
143	}
144	
145	/// Wrap a STRING-typed SQL expression `var` into the column's target type.
146	/// `Struct` is handled by [`column_expr`], never here.
147	pub(crate) fn wrap_scalar(ty: &BqType, var: &str) -> String {
148	    match ty {
149	        BqType::String => var.to_string(),
150	        BqType::Bytes => format!("FROM_BASE64({var})"),
151	        BqType::Geography => format!("ST_GEOGFROMTEXT({var})"),
152	        BqType::Json => format!("PARSE_JSON({var})"),
153	        BqType::Struct => unreachable!("struct is handled by column_expr"),
154	        other => format!("CAST({var} AS {})", other.sql_keyword()),
155	    }
156	}
157	
158	/// Build the `field AS name, …` list for a STRUCT, recursing into each child.
159	fn struct_field_list(
160	    fields: &[FieldSpec],
161	    json_var: &str,
162	    base_path: &str,
163	    depth: usize,
164	) -> String {
165	    fields
166	        .iter()
167	        .map(|f| {
168	            let child_path = format!("{base_path}{}", json_path_segment(&f.name));
169	            let expr = column_expr(f, json_var, &child_path, depth);
170	            format!("{expr} AS {}", quote_ident(&f.name))
171	        })
172	        .collect::<Vec<_>>()
173	        .join(", ")
174	}
175	
176	/// Generate the SQL extraction expression for one column.
177	///
178	/// `json_var` is always the UNNEST element alias or the top-level row variable;
179	/// `path` is always a JSONPath relative to that variable's JSON root (e.g. `"$.field"`
180	/// at top level, `"$.child"` inside a nested struct). `depth` keeps nested `UNNEST`
181	/// aliases unique (`e{depth}` for struct elements, `x{depth}` for scalars).
182	pub(crate) fn column_expr(field: &FieldSpec, json_var: &str, path: &str, depth: usize) -> String {
183	    if field.repeated {
184	        if field.ty == BqType::Struct {
185	            let elem = format!("e{depth}");
186	            let fields = struct_field_list(&field.fields, &elem, "$", depth + 1);
187	            format!(
188	                "ARRAY(SELECT AS STRUCT {fields} FROM UNNEST(JSON_QUERY_ARRAY({json_var}, {p})) AS {elem})",
189	                p = sql_str(path)
190	            )
191	        } else {
192	            let x = format!("x{depth}");
193	            let src = if field.ty == BqType::Json {
194	                format!("JSON_QUERY_ARRAY({json_var}, {p})", p = sql_str(path))
195	            } else {
196	                format!("JSON_VALUE_ARRAY({json_var}, {p})", p = sql_str(path))
197	            };
